update public.lessons l set enhancements = $ench${"industryStory":"A team shipped a \"forgotten password\" feature that technically worked — but the reset email took eleven minutes to arrive because nobody had specified a time limit. The acceptance criteria said only \"user receives a reset link\". Adding one word — \"within 60 seconds\" — to the Then clause would have caught it. Now the first thing I check on any criterion is whether every outcome is measurable.","visualAid":{"type":"comparison","title":"Given/When/Then maps to a test","headers":["Clause","Meaning","Test element"],"rows":[["Given","Initial context","Precondition & test data"],["When","The action / event","Test step"],["Then","Expected outcome","Expected result / assertion"]]},"davidTip":"Read every \"Then\" clause and ask: could two reasonable people disagree about whether it passed? If yes, it is not done. \"The page loads quickly\" fails that test; \"the page loads within 2 seconds\" passes it. Measurable outcomes are the whole game.","miniChallenge":"Write a Given/When/Then acceptance criterion for the failure case of a login story (wrong password).","modelAnswer":"## Example\n**Given** I am a registered user on the login page,\n**When** I enter a valid email but an incorrect password,\n**Then** I see the message \"Email or password is incorrect\" and I remain on the login page.","badGood":{"label":"acceptance criteria","bad":"\"The login should work properly and be secure.\" — unmeasurable, no scenario, impossible to pass or fail objectively.","good":"\"Given a registered user, When they submit the correct email and password, Then they are taken to their dashboard within 2 seconds.\" — specific, scenario-based, and objectively testable."}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'istqb-foundation-masterclass'
  and m.module_number = 10 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A team I coached kept marking stories \"done\" that came back broken a sprint later. The problem wasn’t skill — it was that \"done\" meant \"the feature demoed\". We wrote an explicit Definition of Done: reviewed, unit-tested, regression green, no critical defects. The velocity number dropped for two sprints because we were finally being honest — and the flow of returning defects dried up completely.","visualAid":{"type":"comparison","title":"Acceptance criteria vs Definition of Done","headers":["Aspect","Acceptance criteria","Definition of Done"],"rows":[["Scope","One specific story","Every backlog item"],["Question answered","What must this story do?","What quality bar must all work meet?"],["Written by","PO + team per story","The whole team, once"],["Changes","Per story","Rarely; applies to all"],["Example","\"Reset link arrives in 60s\"","\"Code reviewed & unit-tested\""]]},"davidTip":"When someone says a story is \"done\", ask two separate questions: \"does it meet the acceptance criteria?\" and \"does it meet our Definition of Done?\" The second question is where the honest conversation happens — and it is the one immature teams quietly skip.","miniChallenge":"Sort these into \"acceptance criteria\" or \"Definition of Done\": (a) \"reset email arrives within 60 seconds\"; (b) \"all new code is peer-reviewed\"; (c) \"automated regression suite is green\".","modelAnswer":"## Example\n(a) is an **acceptance criterion** — it’s specific to the password-reset story. (b) and (c) are **Definition of Done** items — they are the quality bar every story must clear, regardless of what the story does.","badGood":{"label":"declaring work “done”","bad":"\"It works on my machine and I showed it in the demo, so it’s done.\" — meets neither review nor testing gates.","good":"\"It meets its acceptance criteria, it’s peer-reviewed, unit and regression tests are green, and there are no critical defects — so it’s done.\" — the full DoD is satisfied."}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
