  and m.module_number = 10 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team relied entirely on an automated regression suite and was proud it was always green — yet customers kept reporting odd crashes. The scripts only ever checked what the team had already thought of. We introduced two 90-minute charter-driven exploratory sessions per sprint, and in the first session alone found three crashes on malformed input that no script would ever have tried. Exploration finds the bugs your imagination didn’t.","visualAid":{"type":"comparison","title":"Exploratory vs scripted testing","headers":["Dimension","Exploratory","Scripted"],"rows":[["Design & execution","Simultaneous","Separated (design first)"],["Best at finding","Unknown unknowns","Known, expected cases"],["Documentation","Charters & session notes","Detailed test cases"],["Repeatability","Lower","High"],["Fit with Agile","Excellent (fast, adaptive)","Good for regression/automation"]]},"davidTip":"The best testers I’ve worked with never treat exploratory and scripted testing as rivals. They automate the boring, repeatable regression so a machine runs it every build, and they spend their scarce human attention exploring with charters. That split — machines for the known, humans for the unknown — is where quality is really won.","miniChallenge":"Write a complete test charter for a \"shopping cart\" feature: state the mission (what and why) and a sensible time-box.","modelAnswer":"## Example\n**Charter:** Explore the shopping cart with quantity changes and item removal to discover total-price and stock-count errors. **Time-box:** 60 minutes. **Notes to capture:** any incorrect totals, negative quantities accepted, or stock counts going wrong — plus open questions for the team debrief.","badGood":{"label":"an exploratory session","bad":"\"I’ll just have a click around the new feature for a bit and see if anything breaks.\" — no mission, no time-box, no record of coverage.","good":"\"Charter: explore checkout with invalid discount codes to find pricing errors; time-box 60 minutes; capture findings and open questions for debrief.\" — focused, accountable, reportable."},"managersReview":{"intro":"If I reviewed your Agile testing work as a lead, here’s what I’d look for:","strengths":["You engage from refinement onwards, not just at \"test time\"","Your acceptance criteria are measurable and scenario-based","You run charter-driven exploratory sessions, not aimless clicking","You can clearly separate acceptance criteria from the Definition of Done"],"improvements":["Bring test ideas and risks into planning, not after coding","Make every \"Then\" clause objectively measurable","Time-box exploratory sessions and always debrief the findings"],"gaps":["Waiting for a build before doing any test activity","Confusing \"meets acceptance criteria\" with \"done\"","Running exploratory testing with no charter or notes to show for it"]},"portfolioBuilder":"Create an \"Agile testing pack\" for your portfolio: for one sample feature, include (1) the user story checked against INVEST, (2) Given/When/Then acceptance criteria covering happy and negative paths, (3) a team Definition of Done, and (4) an exploratory test charter with session notes. This single artefact demonstrates the whole module in action.","resourcePreview":{"name":"Agile Testing Toolkit","purpose":"Templates for user stories, Given/When/Then acceptance criteria, a Definition of Done checklist, and a session-based exploratory test charter.","whenToUse":"Use it whenever you join a Scrum team or refine a backlog item.","formats":["PDF","DOCX"]}}$ench$::jsonb
